parameters.jsCode:
const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

const receivedSignature = headers['x-kredo-signature'] || headers['X-KREDO-Signature'] || '';
const expectedSignature = 'sha256=' + (item.computedSignature || '');

if (!receivedSignature || receivedSignature !== expectedSignature) {
  throw new Error('Signature HMAC invalide (X-KREDO-Signature) — requête rejetée');
}

const required = ['runId', 'workflowId', 'entityType', 'entityId', 'workspaceId', 'userId', 'callbackUrl', 'input'];
for (const field of required) {
  if (!body[field]) throw new Error(`Champ requis manquant dans le payload : ${field}`);
}

if (body.entityType !== 'company') {
  throw new Error('intel-010-refresh requiert entityType="company"');
}

const input = body.input || {};

// Routage par opération — seul account_scan (Lot 1) est implémenté aujourd'hui.
// Toute opération future (ex: veille legacy client_intelligence_refresh) devra
// ajouter une branche ici sans casser celle-ci, cf. investigation obligatoire Lot 1.
// Deux validations distinctes (correctif Lot 2) : un champ manquant et un champ
// invalide sont deux causes racines différentes — le message doit permettre de
// les distinguer immédiatement plutôt que d'afficher "undefined" sans contexte.
// Pas de fallback silencieux (`input.operation || 'account_scan'`) : le contrat
// reste strict pour détecter les futurs payloads incomplets.
if (!input.operation) {
  throw new Error('input.operation est requis. Valeur attendue : "account_scan". Vérifier le payload envoyé par /api/n8n/trigger.');
}

if (input.operation !== 'account_scan') {
  throw new Error(`Opération non supportée par intel-010-refresh : "${input.operation}".`);
}

if (input.informationMode !== 'find' && input.informationMode !== 'verify') {
  throw new Error('input.informationMode doit valoir "find" ou "verify"');
}

const contactMode = input.contactMode || 'none';
if (!['none', 'identify', 'confirm'].includes(contactMode)) {
  throw new Error('input.contactMode doit valoir "none", "identify" ou "confirm"');
}
const requestedRoles = Array.isArray(input.requestedRoles)
  ? input.requestedRoles.map((r) => String(r || '').trim()).filter(Boolean).slice(0, 12)
  : [];
const maxContacts = Math.max(1, Math.min(10, Number.isFinite(Number(input.maxContacts)) ? Math.trunc(Number(input.maxContacts)) : 5));

const knownCompany = input.knownCompany || {};

return [{
  json: {
    runId: body.runId,
    workflowId: body.workflowId,
    workspaceId: body.workspaceId,
    userId: body.userId,
    companyId: body.entityId,
    callbackUrl: body.callbackUrl,
    operation: input.operation,
    informationMode: input.informationMode,
    contactMode,
    requestedFields: Array.isArray(input.requestedFields) ? input.requestedFields : [],
    requestedFacts: Array.isArray(input.requestedFacts) ? input.requestedFacts : [],
    requestedRoles,
    maxContacts,
    selectedSiren: input.selectedSiren || null,
    websiteHint: input.websiteHint || null,
    locationHint: input.locationHint || null,
    autoApplyOfficialMissing: input.autoApplyOfficialMissing === true,
    knownCompany: {
      name: knownCompany.name || null,
      legalName: knownCompany.legalName || null,
      website: knownCompany.website || null,
      siren: knownCompany.siren || null,
      nafCode: knownCompany.nafCode || null,
      sectorId: knownCompany.sectorId || null,
    },
  }
}];

const upstream = $('Validate & Route').item.json;
const companyRaw = $input.first().json;
const company = Array.isArray(companyRaw) ? companyRaw[0] : companyRaw;

if (!company || !company.id) {
  throw new Error(`Compte introuvable ou hors workspace : ${upstream.companyId}`);
}

const activeProposals = $('Load Active Proposals').all().map((i) => i.json);
const proposedFieldNames = new Set(
  activeProposals.filter((p) => ['proposed', 'needs_review', 'conflicting', 'validated'].includes(p.status)).map((p) => p.attribute_name)
);

// Champs "objectifs" pris en charge nativement par le CRM (cf. crm_attribute_is_allowed
// côté migration Lot 0 — le secteur et le CA sont volontairement exclus du V1 du scan :
// pas de mapping fiable secteur↔registre, pas de source fiable pour le CA en accès libre).
const ALL_FIELDS = ['legal_name', 'siren', 'naf_code', 'hq_location', 'employee_count', 'website', 'description'];
const ALL_FACTS = [
  'business_model', 'primary_activity', 'technology', 'competitor', 'partner', 'market',
  'strategic_priority', 'transformation_program', 'establishment_count', 'growth_trend',
  'geographic_reach', 'value_proposition', 'differentiators', 'market_position',
  'marketing_position', 'target_customers',
];

function isFieldMissing(fieldName) {
  switch (fieldName) {
    case 'legal_name': return !company.legal_name;
    case 'siren': return !company.siren;
    case 'naf_code': return !company.naf_code;
    case 'hq_location': return !company.hq_location;
    case 'employee_count': return company.employee_count === null || company.employee_count === undefined;
    case 'website': return !company.website;
    case 'description': return !company.description;
    default: return true;
  }
}

let requestedFields = Array.isArray(upstream.requestedFields) && upstream.requestedFields.length > 0
  ? upstream.requestedFields.filter((f) => ALL_FIELDS.includes(f))
  : ALL_FIELDS.slice();

if (upstream.informationMode === 'find') {
  // Mode "trouver les informations manquantes" : uniquement les champs vides côté CRM,
  // et on n'insiste pas sur un champ qui a déjà une proposition active en attente de décision humaine.
  requestedFields = requestedFields.filter((f) => isFieldMissing(f) && !proposedFieldNames.has(f));
}
// Mode "verify" : on garde la liste complète pour vérifier même les champs déjà renseignés.

let requestedFacts = Array.isArray(upstream.requestedFacts) && upstream.requestedFacts.length > 0
  ? upstream.requestedFacts.filter((f) => ALL_FACTS.includes(f))
  : ALL_FACTS.slice();

if (upstream.informationMode === 'find') {
  // Les faits n'ont pas d'équivalent "vide/rempli" direct sur companies — on exclut seulement
  // ceux qui ont déjà une proposition active, pour ne pas spammer l'utilisateur de doublons.
  requestedFacts = requestedFacts.filter((f) => !proposedFieldNames.has(f));
}

return [{
  json: {
    ...upstream,
    company,
    activeProposals,
    requestedFields,
    requestedFacts,
  }
}];

const ctx = $('Build Scan Plan').first().json;
const registryResponse = $input.first().json;

// Codes "tranche d'effectif salarié" INSEE — approximation médiane de la fourchette,
// jamais un chiffre exact (cf. Lot 1 §5 employee_count : donnée bracket, pas ponctuelle).
const TRANCHE_EFFECTIF_MIDPOINT = {
  '00': 0, '01': 1, '02': 4, '03': 7, '11': 15, '12': 35, '21': 75, '22': 150,
  '31': 225, '32': 375, '41': 750, '42': 1500, '51': 3500, '52': 7500, '53': 15000,
};

function buildHqLocation(siege) {
  if (!siege) return null;
  const parts = [siege.adresse, siege.code_postal, siege.libelle_commune].filter(Boolean);
  return parts.length > 0 ? parts.join(', ') : null;
}

function normalizeNaf(code) {
  if (!code) return null;
  return String(code).toUpperCase().replace(/\./g, '');
}

function mapCandidate(r) {
  return {
    siren: r.siren,
    legalName: r.nom_complet || r.nom_raison_sociale || r.sigle || r.siren,
    nafCode: normalizeNaf(r.activite_principale),
    hqLocation: buildHqLocation(r.siege),
    employeeCountEstimate: r.siege && r.siege.tranche_effectif_salarie != null
      ? (TRANCHE_EFFECTIF_MIDPOINT[String(r.siege.tranche_effectif_salarie)] ?? null)
      : (r.tranche_effectif_salarie != null ? (TRANCHE_EFFECTIF_MIDPOINT[String(r.tranche_effectif_salarie)] ?? null) : null),
    raw: r,
  };
}

const hadError = !!(registryResponse && registryResponse.error);
const results = (!hadError && registryResponse && Array.isArray(registryResponse.results)) ? registryResponse.results : [];
const candidates = results.map(mapCandidate);

let resolution;
const warnings = [];

if (hadError) {
  warnings.push('Le registre officiel (recherche-entreprises.api.gouv.fr) était indisponible pendant ce scan.');
  resolution = { status: 'not_found', siren: null, matchMethod: null, candidates: [] };
} else if (ctx.selectedSiren) {
  const exact = candidates.find((c) => c.siren === ctx.selectedSiren);
  resolution = {
    status: 'resolved',
    siren: ctx.selectedSiren,
    matchMethod: 'selected_siren',
    candidates: [],
    _winner: exact || { siren: ctx.selectedSiren, legalName: ctx.knownCompany.legalName || ctx.company.legal_name || ctx.company.name, nafCode: null, hqLocation: null, employeeCountEstimate: null, raw: null },
  };
} else if (candidates.length === 0) {
  resolution = { status: 'not_found', siren: null, matchMethod: null, candidates: [] };
} else {
  // Score déterministe : similarité de nom (Jaccard sur tokens) + bonus localisation.
  const targetName = (ctx.knownCompany.legalName || ctx.knownCompany.name || ctx.company.legal_name || ctx.company.name || '').toLowerCase();
  const targetTokens = new Set(targetName.split(/[^a-z0-9]+/).filter((t) => t.length > 1));
  const locationHint = (ctx.locationHint || ctx.company.hq_location || '').toLowerCase();

  function nameScore(candidateName) {
    const tokens = new Set(String(candidateName || '').toLowerCase().split(/[^a-z0-9]+/).filter((t) => t.length > 1));
    if (targetTokens.size === 0 || tokens.size === 0) return 0;
    let inter = 0;
    for (const t of targetTokens) if (tokens.has(t)) inter += 1;
    const union = new Set([...targetTokens, ...tokens]).size;
    return union > 0 ? inter / union : 0;
  }

  function locationScore(hq) {
    if (!locationHint || !hq) return 0;
    const hqLower = hq.toLowerCase();
    return locationHint.split(/[^a-z0-9]+/).filter((t) => t.length > 2).some((t) => hqLower.includes(t)) ? 0.25 : 0;
  }

  const scored = candidates.map((c) => ({
    ...c,
    matchScore: Math.round(Math.min(1, 0.75 * nameScore(c.legalName) + locationScore(c.hqLocation)) * 1000) / 1000,
  })).sort((a, b) => b.matchScore - a.matchScore);

  const top = scored[0];
  const second = scored[1];
  const clearWinner = top && top.matchScore >= 0.5 && (!second || (top.matchScore - second.matchScore) >= 0.25);

  if (clearWinner) {
    resolution = { status: 'resolved', siren: top.siren, matchMethod: 'name_location_match', candidates: [], _winner: top };
  } else {
    resolution = {
      status: 'ambiguous',
      siren: null,
      matchMethod: null,
      candidates: scored.slice(0, 5).map((c) => ({
        siren: c.siren, legalName: c.legalName, nafCode: c.nafCode, hqLocation: c.hqLocation, matchScore: c.matchScore,
      })),
    };
  }
}

return [{
  json: {
    ...ctx,
    resolution: {
      status: resolution.status,
      siren: resolution.siren || null,
      matchMethod: resolution.matchMethod || null,
      candidates: resolution.candidates || [],
    },
    resolutionWinner: resolution._winner || null,
    warnings,
  }
}];

const ctx = $('Resolve Entity').first().json;
const raw = $input.all();
const errorItem = raw.find((i) => i.json && i.json.error);

let siteText = '';
let siteUrl = ctx.websiteHint || ctx.knownCompany.website || ctx.company.website || null;

if (!errorItem && siteUrl) {
  const html = (raw[0] && (raw[0].json.data || raw[0].json.body || raw[0].json.html)) || '';
  // Extraction texte best-effort (pas de dépendance HTML parser externe) : on retire scripts/styles/balises.
  siteText = String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 6000);
}

return [{
  json: {
    ...ctx,
    siteUrl,
    siteText,
    siteFetchFailed: !!errorItem || !siteText,
  }
}];

const ctx = $('Shape Official Site').first().json;
const raw = $input.all();
const errorItem = raw.find((i) => i.json && i.json.error);

const newsItems = errorItem ? [] : raw
  .filter((i) => i.json && i.json.title)
  .slice(0, 8)
  .map((i) => ({
    title: i.json.title,
    url: i.json.link,
    publishedAt: i.json.isoDate || i.json.pubDate || null,
    snippet: (i.json.contentSnippet || i.json.content || '').slice(0, 400),
  }));

return [{ json: { ...ctx, newsItems } }];

