parameters.jsCode:
const response = $input.first().json;
const upstream = $('Assemble Extraction Prompt').item.json;
const textBlock = (response.content || []).find((b) => b.type === 'text');
const content = textBlock && textBlock.text;

if (!content) {
  throw new Error('Le LLM a renvoyé un contenu vide');
}

let parsed;
try {
  const clean = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  throw new Error('Réponse LLM non-JSON : ' + content.slice(0, 200));
}

if (parsed.schema_version !== 1) {
  throw new Error('schema_version doit valoir 1');
}

const ALLOWED_FACT_ATTRS = new Set([
  'business_model', 'primary_activity', 'technology', 'competitor', 'partner', 'market',
  'strategic_priority', 'transformation_program', 'establishment_count', 'growth_trend',
  'geographic_reach', 'value_proposition', 'differentiators', 'market_position',
  'marketing_position', 'target_customers',
]);

if (!Array.isArray(parsed.facts)) {
  throw new Error('facts manquant ou invalide');
}
for (const f of parsed.facts) {
  if (!ALLOWED_FACT_ATTRS.has(f.attribute)) {
    throw new Error(`Attribut de fait non autorisé : "${f.attribute}"`);
  }
  if (!f.text || typeof f.text !== 'string') {
    throw new Error(`Fait sans texte pour l'attribut ${f.attribute}`);
  }
  if (typeof f.explicit !== 'boolean') {
    throw new Error(`Fait "${f.attribute}" sans indicateur explicit (booléen requis)`);
  }
}

if (parsed.description !== null && parsed.description !== undefined && typeof parsed.description !== 'string') {
  throw new Error('description doit être une chaîne ou null');
}

const allowedEmailStatuses = new Set(['public', 'confirmed', 'inferred', 'unknown']);
const rawContacts = Array.isArray(parsed.contact_candidates) ? parsed.contact_candidates : [];
// Le LLM ne fournit plus confidence_score ni suggested_action (Lot 3 §4/§5) — un
// nœud déterministe en aval (Build Proposals & Sources) les calcule seul à partir
// du CRM et des sources. Un candidat sans full_name OU sans evidence non vide est
// rejeté silencieusement ici (pas d'exception qui ferait échouer tout le scan pour
// un seul mauvais candidat) plutôt que d'être propagé sans preuve (§3).
const llmContactCandidates = rawContacts.slice(0, upstream.maxContacts || 5).map((c, index) => {
  const fullName = typeof c.full_name === 'string' ? c.full_name.trim() : '';
  const evidence = typeof c.evidence === 'string' ? c.evidence.trim() || null : null;
  if (!fullName || !evidence) return null;
  const emailStatus = allowedEmailStatuses.has(c.email_status) ? c.email_status : 'unknown';
  return {
    rawIndex: index,
    firstName: typeof c.first_name === 'string' ? c.first_name.trim() || null : null,
    lastName: typeof c.last_name === 'string' ? c.last_name.trim() || null : null,
    fullName,
    jobTitle: typeof c.job_title === 'string' ? c.job_title.trim() || null : null,
    department: typeof c.department === 'string' ? c.department.trim() || null : null,
    relationshipRole: typeof c.relationship_role === 'string' ? c.relationship_role.trim() || null : null,
    email: typeof c.email === 'string' ? c.email.trim() || null : null,
    emailStatus,
    phone: typeof c.phone === 'string' ? c.phone.trim() || null : null,
    linkedinUrl: typeof c.linkedin_url === 'string' ? c.linkedin_url.trim() || null : null,
    evidence,
  };
}).filter((c) => c !== null);

return [{
  json: {
    ...upstream,
    llmDescription: parsed.description || null,
    llmFacts: parsed.facts,
    llmContactCandidates,
    llmUsage: {
      inputTokens: (response.usage && response.usage.input_tokens) || null,
      outputTokens: (response.usage && response.usage.output_tokens) || null,
      model: response.model || 'claude-sonnet-5',
    },
  }
}];

// Lu depuis le nœud nommé explicitement (pas $input) : "Load Workspace Contacts" a
// été inséré juste avant celui-ci (Lot 3) pour le rapprochement CRM des candidats
// contacts — $input serait alors sa réponse HTTP, pas le ctx attendu. Même pattern
// déjà utilisé par "Reconcile & Prepare Writes" (à propos de "Merge Scan Result").
const ctx = $('Parse & Validate LLM Output').item.json;
const existingContactRows = $('Load Workspace Contacts').all().map((i) => i.json).filter((r) => r && r.id);

// ── Fonctions déterministes partagées ────────────────────────────────────────
function simpleHash(str) {
  let h = 5381;
  const s = String(str == null ? '' : str);
  for (let i = 0; i < s.length; i += 1) {
    h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  }
  return (h >>> 0).toString(16);
}

function normalizeText(v) {
  if (v === null || v === undefined) return null;
  const t = String(v).replace(/\s+/g, ' ').trim();
  return t.length > 0 ? t : null;
}

const RELIABILITY_BY_SOURCE_TYPE = {
  regulatory_filing: 0.97,
  official_site: 0.75,
  news_media: 0.55,
};

function freshnessScore(publishedAt, defaultScore) {
  if (!publishedAt) return defaultScore;
  const d = new Date(publishedAt);
  if (isNaN(d)) return defaultScore;
  const ageDays = (Date.now() - d.getTime()) / 86400000;
  if (ageDays <= 30) return 1.0;
  if (ageDays >= 730) return 0.3;
  return Math.max(0.3, Math.min(1, 1 - (ageDays - 30) / 700));
}

// reliability(0-1) x0.40, corroboration(0-2 sources)x0.20, freshness x0.15, explicitness x0.25 ;
// une contradiction avec la valeur CRM actuelle (mode verify) réduit la confiance de 40%.
function computeConfidence({ reliability, corroborationCount, freshness, explicitness, hasContradiction }) {
  let score = 0.40 * reliability + 0.20 * Math.min(1, corroborationCount / 2) + 0.15 * freshness + 0.25 * explicitness;
  if (hasContradiction) score *= 0.6;
  return Math.round(Math.max(0, Math.min(1, score)) * 1000) / 1000;
}

const nowIso = new Date().toISOString();
const sourcesByKey = new Map();
const fieldProposals = [];
const factProposals = [];
const contactCandidates = [];
const warnings = [...(ctx.warnings || [])];

// ── Sources ───────────────────────────────────────────────────────────────
function upsertSource({ key, type, name, url, publishedAt, excerpt, method }) {
  if (sourcesByKey.has(key)) return sourcesByKey.get(key);
  let canonicalUrl = url || null;
  if (url) {
    try {
      const u = new URL(url);
      u.search = '';
      u.hash = '';
      canonicalUrl = u.toString();
    } catch (e) { /* garde l'url brute */ }
  }
  const source = {
    workspace_id: ctx.workspaceId,
    source_type: type,
    source_name: name,
    source_url: url || null,
    canonical_url: canonicalUrl,
    published_at: publishedAt || null,
    collected_at: nowIso,
    source_key: key,
    evidence_excerpt: (excerpt || '').slice(0, 500),
    reliability_score: RELIABILITY_BY_SOURCE_TYPE[type] ?? 0.5,
    collection_method: method,
    technical_metadata: { collector: 'intel-010-refresh:account_scan', runId: ctx.runId },
  };
  sourcesByKey.set(key, source);
  return source;
}

let registrySource = null;
if (ctx.resolutionWinner && ctx.resolution.status === 'resolved') {
  const w = ctx.resolutionWinner;
  registrySource = upsertSource({
    key: `account_scan:registry:${w.siren}`,
    type: 'regulatory_filing',
    name: "Recherche d'entreprises (data.gouv.fr / INSEE Sirene)",
    url: `https://recherche-entreprises.api.gouv.fr/search?q=${w.siren}`,
    publishedAt: null,
    excerpt: `SIREN ${w.siren} — ${w.legalName}`,
    method: 'api',
  });
}

let siteSource = null;
if (ctx.siteUrl && !ctx.siteFetchFailed) {
  siteSource = upsertSource({
    key: `account_scan:site:${simpleHash(ctx.siteUrl)}`,
    type: 'official_site',
    name: ctx.company.name || 'Site officiel',
    url: ctx.siteUrl,
    publishedAt: null,
    excerpt: (ctx.siteText || '').slice(0, 500),
    method: 'scrape',
  });
}

const newsSourcesByHeadline = new Map();
for (const n of (ctx.newsItems || [])) {
  const src = upsertSource({
    key: `account_scan:news:${simpleHash(n.url || n.title)}`,
    type: 'news_media',
    name: 'Presse',
    url: n.url,
    publishedAt: n.publishedAt,
    excerpt: n.snippet || n.title,
    method: 'scrape',
  });
  newsSourcesByHeadline.set(n.title, src);
}

// ── Champs objectifs issus du registre (déterministes, pas de LLM) ──────────
const winner = ctx.resolutionWinner;
if (winner && registrySource) {
  const registryFieldValues = {
    legal_name: winner.legalName || null,
    siren: winner.siren || null,
    naf_code: winner.nafCode || null,
    hq_location: winner.hqLocation || null,
    employee_count: winner.employeeCountEstimate,
  };

  for (const fieldName of ['legal_name', 'siren', 'naf_code', 'hq_location', 'employee_count']) {
    if (!ctx.requestedFields.includes(fieldName)) continue;
    const proposedRaw = registryFieldValues[fieldName];
    if (proposedRaw === null || proposedRaw === undefined || proposedRaw === '') continue;

    const currentValue = ctx.company[fieldName] === undefined ? null : ctx.company[fieldName];
    const isEstimate = fieldName === 'employee_count';
    const normalizedProposed = typeof proposedRaw === 'string' ? normalizeText(proposedRaw) : proposedRaw;
    const normalizedCurrent = typeof currentValue === 'string' ? normalizeText(currentValue) : currentValue;
    const hasContradiction = normalizedCurrent !== null && normalizedCurrent !== normalizedProposed;

    if (normalizedCurrent === normalizedProposed) continue; // rien à proposer, déjà à jour

    const confidence = computeConfidence({
      reliability: RELIABILITY_BY_SOURCE_TYPE.regulatory_filing,
      corroborationCount: 1,
      freshness: 1.0,
      explicitness: isEstimate ? 0.6 : 1.0,
      hasContradiction,
    });

    fieldProposals.push({
      attribute_name: fieldName,
      current_value: normalizedCurrent,
      proposed_value: normalizedProposed,
      normalized_value: normalizedProposed,
      confidence_score: confidence,
      source_keys: [registrySource.source_key],
      justification: isEstimate
        ? `Effectif estimé à partir de la tranche déclarée au registre officiel (SIREN ${winner.siren}).`
        : `Donnée issue du registre officiel (SIREN ${winner.siren}).`,
    });
  }
}

// ── Website (uniquement si un hint explicite a été fourni — pas de découverte auto) ──
if (ctx.requestedFields.includes('website') && ctx.websiteHint) {
  const currentWebsite = normalizeText(ctx.company.website);
  const proposedWebsite = normalizeText(ctx.websiteHint);
  if (proposedWebsite && proposedWebsite !== currentWebsite) {
    fieldProposals.push({
      attribute_name: 'website',
      current_value: currentWebsite,
      proposed_value: proposedWebsite,
      normalized_value: proposedWebsite,
      confidence_score: computeConfidence({ reliability: 0.9, corroborationCount: 1, freshness: 1.0, explicitness: 1.0, hasContradiction: !!currentWebsite }),
      source_keys: [],
      justification: 'URL fournie explicitement pour ce scan (websiteHint).',
    });
  }
} else if (ctx.requestedFields.includes('website') && !ctx.company.website && !ctx.websiteHint) {
  warnings.push('Site officiel introuvable automatiquement (aucun fournisseur de recherche payant configuré) — fournir websiteHint pour le vérifier.');
}

// ── Description (interprétative, issue du LLM à partir du site) ─────────────
if (ctx.requestedFields.includes('description') && ctx.llmDescription && siteSource) {
  const currentDescription = normalizeText(ctx.company.description);
  const proposedDescription = normalizeText(ctx.llmDescription);
  if (proposedDescription && proposedDescription !== currentDescription) {
    fieldProposals.push({
      attribute_name: 'description',
      current_value: currentDescription,
      proposed_value: proposedDescription,
      normalized_value: proposedDescription,
      confidence_score: computeConfidence({ reliability: RELIABILITY_BY_SOURCE_TYPE.official_site, corroborationCount: 1, freshness: 1.0, explicitness: 0.8, hasContradiction: !!currentDescription }),
      source_keys: [siteSource.source_key],
      justification: 'Résumé généré à partir du contenu du site officiel.',
    });
  }
}

// ── Faits interprétatifs (LLM), un par fait retenu ──────────────────────────
const MULTI_CARDINALITY = new Set(['technology', 'competitor', 'partner', 'market', 'strategic_priority', 'transformation_program', 'differentiators', 'target_customers']);

for (const fact of (ctx.llmFacts || [])) {
  if (!ctx.requestedFacts.includes(fact.attribute)) continue;
  const text = normalizeText(fact.text);
  if (!text) continue;

  const sourceKeys = [];
  if (siteSource) sourceKeys.push(siteSource.source_key);
  const matchingNewsSource = [...newsSourcesByHeadline.values()].find((s) => text.toLowerCase().includes((s.evidence_excerpt || '').slice(0, 30).toLowerCase()));
  if (matchingNewsSource) sourceKeys.push(matchingNewsSource.source_key);

  const corroborationCount = sourceKeys.length;
  const confidence = computeConfidence({
    reliability: RELIABILITY_BY_SOURCE_TYPE.official_site,
    corroborationCount,
    freshness: 1.0,
    explicitness: fact.explicit ? 1.0 : 0.4,
    hasContradiction: false,
  });

  const cardinality = MULTI_CARDINALITY.has(fact.attribute) ? 'multi' : 'single';
  const proposalKeySuffix = cardinality === 'multi' ? `:${simpleHash(text.toLowerCase())}` : '';

  factProposals.push({
    attribute_name: fact.attribute,
    cardinality,
    proposal_key_suffix: proposalKeySuffix,
    proposed_value: text,
    normalized_value: text,
    confidence_score: confidence,
    source_keys: sourceKeys.length > 0 ? sourceKeys : (siteSource ? [siteSource.source_key] : []),
    justification: fact.explicit
      ? 'Énoncé explicitement dans les preuves collectées (site officiel / presse).'
      : 'Déduction raisonnable à partir des preuves collectées — non explicite.',
  });
}

// ── Rapprochement CRM + score déterministe + normalisation contacts (Lot 3) ──
// Le LLM ne fournit plus ni confidenceScore ni suggestedAction pour les contacts
// (§4/§5) : tout est recalculé ici à partir du CRM réel (existingContactRows,
// chargé par le nœud "Load Workspace Contacts") et des sources collectées, jamais
// depuis une opinion du modèle qui n'a aucune visibilité sur le CRM.

function normalizeEmailForMatch(v) {
  const t = normalizeText(v);
  return t ? t.toLowerCase() : null;
}

function normalizeLinkedinForMatch(v) {
  const t = normalizeText(v);
  if (!t) return null;
  return t
    .toLowerCase()
    .replace(/^https?:\/\/(www\.)?/, '')
    .replace(/[?#].*$/, '')
    .replace(/\/+$/, '');
}

function normalizeNameForMatch(v) {
  const t = normalizeText(v);
  if (!t) return null;
  return t
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

// Plafonds de confiance par type de source la plus fiable retenue pour le candidat
// (§4 — nom+fonction explicites sur site officiel/registre : 0.95 ; presse : 0.80 ;
// aucune source forte identifiée : 0.55). Un email inféré plafonne en plus à 0.45
// quel que soit le reste (jamais "haute confiance" sur la seule base d'un email deviné).
const CONTACT_SOURCE_CEILING = { regulatory_filing: 0.95, official_site: 0.95, news_media: 0.80 };
const CONTACT_DEFAULT_CEILING = 0.55;
const INFERRED_EMAIL_CEILING = 0.45;

function contactSourceCeiling(sourceKeys, sourcesMap) {
  let ceiling = 0;
  for (const key of sourceKeys) {
    const src = sourcesMap.get(key);
    if (!src) continue;
    const c = CONTACT_SOURCE_CEILING[src.source_type] ?? CONTACT_DEFAULT_CEILING;
    if (c > ceiling) ceiling = c;
  }
  return ceiling > 0 ? ceiling : CONTACT_DEFAULT_CEILING;
}

if (ctx.contactMode === 'identify' || ctx.contactMode === 'confirm') {
  const fallbackSource = siteSource || registrySource || null;

  // Index du CRM existant pour rapprochement, même ordre de priorité que le RPC
  // d'import (email > LinkedIn > nom+entreprise) — cf. import_account_scan_contacts.
  const contactsByEmail = new Map();
  const contactsByLinkedin = new Map();
  const contactsByNameAtCompany = new Map();
  for (const row of existingContactRows) {
    const person = row.person || {};
    const emailKey = normalizeEmailForMatch(person.primary_email);
    if (emailKey && !contactsByEmail.has(emailKey)) contactsByEmail.set(emailKey, row);
    const liKey = normalizeLinkedinForMatch(person.linkedin_url);
    if (liKey && !contactsByLinkedin.has(liKey)) contactsByLinkedin.set(liKey, row);
    const nameKey = normalizeNameForMatch(person.full_name);
    if (nameKey && row.company_id === ctx.companyId && !contactsByNameAtCompany.has(nameKey)) {
      contactsByNameAtCompany.set(nameKey, row);
    }
  }

  const rawCandidates = [];
  for (const candidate of (ctx.llmContactCandidates || [])) {
    // §3 : jamais de candidat sans source ni preuve — "evidence" déjà garanti non-vide
    // par "Parse & Validate LLM Output", il reste à vérifier qu'une source existe.
    const sourceKeys = fallbackSource ? [fallbackSource.source_key] : [];
    if (sourceKeys.length === 0 || !candidate.evidence) continue;

    const emailNorm = (candidate.emailStatus === 'public' || candidate.emailStatus === 'confirmed')
      ? normalizeEmailForMatch(candidate.email)
      : null;
    const linkedinNorm = normalizeLinkedinForMatch(candidate.linkedinUrl);
    const nameNorm = normalizeNameForMatch(candidate.fullName);

    const identityKey = emailNorm || linkedinNorm || (nameNorm ? `${nameNorm}:${ctx.companyId}` : null);
    if (!identityKey) continue; // ni email, ni LinkedIn, ni nom exploitable

    let match = null;
    if (emailNorm) match = contactsByEmail.get(emailNorm) || null;
    if (!match && linkedinNorm) match = contactsByLinkedin.get(linkedinNorm) || null;
    if (!match && nameNorm) match = contactsByNameAtCompany.get(nameNorm) || null;

    const existingPersonId = match ? match.person_id : null;
    const existingContactId = match && match.company_id === ctx.companyId ? match.id : null;

    let suggestedAction;
    if (!match) {
      suggestedAction = 'create';
    } else if (!existingContactId) {
      suggestedAction = 'link'; // personne déjà connue ailleurs dans le workspace, pas encore rattachée ici
    } else {
      const hasNewInfo =
        (candidate.jobTitle && candidate.jobTitle !== match.job_title) ||
        (candidate.department && candidate.department !== match.department) ||
        (candidate.relationshipRole && candidate.relationshipRole !== match.relationship_role);
      suggestedAction = hasNewInfo ? 'update' : 'link';
    }

    const ceiling = contactSourceCeiling(sourceKeys, sourcesByKey);
    const explicitness = candidate.evidence && candidate.evidence.length > 0 ? 1.0 : 0.5;
    let confidence = computeConfidence({
      reliability: ceiling,
      corroborationCount: sourceKeys.length,
      freshness: 1.0,
      explicitness,
      hasContradiction: false,
    });
    confidence = Math.min(confidence, ceiling);
    if (candidate.emailStatus === 'inferred') {
      confidence = Math.min(confidence, INFERRED_EMAIL_CEILING);
    }

    rawCandidates.push({
      identityKey,
      candidateKey: 'account_scan:contact:' + simpleHash(identityKey),
      firstName: candidate.firstName,
      lastName: candidate.lastName,
      fullName: candidate.fullName,
      jobTitle: candidate.jobTitle,
      department: candidate.department,
      relationshipRole: candidate.relationshipRole,
      email: candidate.email,
      emailStatus: candidate.emailStatus,
      phone: candidate.phone,
      linkedinUrl: candidate.linkedinUrl,
      sourceKeys,
      evidence: candidate.evidence,
      confidenceScore: confidence,
      existingPersonId,
      existingContactId,
      suggestedAction,
    });
  }

  // Déduplication interne (§3/§6) : deux candidats LLM peuvent viser la même
  // personne (citée dans le site ET dans un titre de presse) — la clé d'identité
  // normalisée les fusionne, on garde la version la plus confiante. candidateKey
  // dérive uniquement de champs normalisés : il reste stable entre deux scans
  // identiques même si la casse/les espaces/les paramètres d'URL varient.
  const byIdentity = new Map();
  for (const c of rawCandidates) {
    const existing = byIdentity.get(c.identityKey);
    if (!existing || c.confidenceScore > existing.confidenceScore) {
      byIdentity.set(c.identityKey, c);
    }
  }
  for (const c of byIdentity.values()) {
    const { identityKey, ...clean } = c;
    contactCandidates.push(clean);
  }
}

return [{
  json: {
    ...ctx,
    sourcesPayload: [...sourcesByKey.values()],
    fieldProposals,
    factProposals,
    contactCandidates,
    warnings,
  }
}];

const ctx = $input.first().json;
const warnings = [...(ctx.warnings || [])];

if (ctx.resolution.status === 'ambiguous') {
  warnings.push(`Entité juridique ambiguë : ${ctx.resolution.candidates.length} candidat(s) trouvé(s) — sélectionner un SIREN et relancer le scan.`);
} else {
  warnings.push('Entité juridique introuvable dans le registre officiel — aucune proposition générée.');
}

return [{
  json: {
    ...ctx,
    sourcesPayload: [],
    fieldProposals: [],
    factProposals: [],
    contactCandidates: [],
    warnings,
  }
}];

// Contexte relu depuis le point de convergence stable — jamais depuis une branche IF
// qui pourrait ne pas s'être exécutée (cf. note sur "Merge Scan Result").
const ctx = $('Merge Scan Result').first().json;

const sourceIdRows = $input.all().map((i) => i.json).filter((r) => r && r.id && r.source_key);
const sourceIdByKey = new Map(sourceIdRows.map((r) => [r.source_key, r.id]));

function simpleHash(str) {
  let h = 5381;
  const s = String(str == null ? '' : str);
  for (let i = 0; i < s.length; i += 1) {
    h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  }
  return (h >>> 0).toString(16);
}

const nowIso = new Date().toISOString();
const warnings = [...(ctx.warnings || [])];
const candidates = [];

for (const fp of (ctx.fieldProposals || [])) {
  candidates.push({
    proposal_key: `account_scan:${ctx.companyId}:${fp.attribute_name}`,
    target_type: 'company',
    target_id: ctx.companyId,
    attribute_name: fp.attribute_name,
    proposed_value: fp.proposed_value,
    normalized_value: fp.normalized_value,
    normalized_value_hash: simpleHash(fp.normalized_value),
    initial_snapshot: { current: fp.current_value === undefined ? null : fp.current_value },
    primary_source_id: fp.source_keys && fp.source_keys[0] ? (sourceIdByKey.get(fp.source_keys[0]) || null) : null,
    origin: 'external',
    confidence_score: fp.confidence_score,
    justification: fp.justification,
    status: fp.confidence_score < 0.45 ? 'needs_review' : 'proposed',
    run_id: ctx.runId,
    workspace_id: ctx.workspaceId,
    proposal_key_source_keys: fp.source_keys || [],
  });
}

for (const factP of (ctx.factProposals || [])) {
  candidates.push({
    proposal_key: `account_scan:${ctx.companyId}:${factP.attribute_name}${factP.proposal_key_suffix || ''}`,
    target_type: 'company',
    target_id: ctx.companyId,
    attribute_name: factP.attribute_name,
    proposed_value: factP.proposed_value,
    normalized_value: factP.normalized_value,
    normalized_value_hash: simpleHash(factP.normalized_value),
    initial_snapshot: { current: null },
    primary_source_id: factP.source_keys && factP.source_keys[0] ? (sourceIdByKey.get(factP.source_keys[0]) || null) : null,
    origin: 'external',
    confidence_score: factP.confidence_score,
    justification: factP.justification,
    status: factP.confidence_score < 0.45 ? 'needs_review' : 'proposed',
    run_id: ctx.runId,
    workspace_id: ctx.workspaceId,
    proposal_key_source_keys: factP.source_keys || [],
  });
}

const activeProposals = ctx.activeProposals || [];
const byKey = new Map(activeProposals.map((p) => [p.proposal_key, p]));

// Les propositions déjà 'validated' ou 'conflicting' portent une décision humaine ou un
// conflit non résolu — on ne les régénère jamais silencieusement (§11 : "aucune application
// directe" et principe général : ne jamais écraser une décision déjà prise).
const untouchedKeys = new Set(activeProposals.filter((p) => ['validated', 'conflicting'].includes(p.status)).map((p) => p.proposal_key));

const toInsert = [];
const staleIdsToDelete = [];

for (const c of candidates) {
  if (untouchedKeys.has(c.proposal_key)) {
    warnings.push(`Proposition déjà en validation ou en conflit pour "${c.attribute_name}" — non régénérée.`);
    continue;
  }
  const existing = byKey.get(c.proposal_key);
  if (existing && ['proposed', 'needs_review'].includes(existing.status)) {
    staleIdsToDelete.push(existing.id);
  }
  const { proposal_key_source_keys, ...row } = c;
  toInsert.push(row);
}

return [{
  json: {
    runId: ctx.runId,
    workspaceId: ctx.workspaceId,
    companyId: ctx.companyId,
    callbackUrl: ctx.callbackUrl,
    company: ctx.company,
    resolution: ctx.resolution,
    sourcesPayload: ctx.sourcesPayload || [],
    sourceIdByKeyList: [...sourceIdByKey.entries()].map(([source_key, id]) => ({ source_key, id })),
    toInsert,
    staleIdsToDelete,
    contactCandidates: ctx.contactCandidates || [],
    llmUsage: ctx.llmUsage || null,
    warnings,
  }
}];

const recon = $('Reconcile & Prepare Writes').first().json;
const insertedRows = $input.all().map((i) => i.json).filter((r) => r && r.id);

// On retrouve les source_keys d'origine de chaque proposition insérée en les recroisant
// par ordre (le POST bulk retourne les lignes dans l'ordre d'insertion — comportement
// PostgREST documenté et déjà utilisé ailleurs dans ce dépôt pour ce même besoin).
const linksPayload = [];
insertedRows.forEach((row, idx) => {
  const candidate = recon.toInsert[idx];
  if (!candidate || !row.primary_source_id) return;
  linksPayload.push({
    workspace_id: row.workspace_id,
    source_id: row.primary_source_id,
    object_type: 'proposal',
    object_id: row.id,
    link_role: 'supporting',
  });
});

return [{ json: { linksPayload } }];

const recon = $('Reconcile & Prepare Writes').first().json;
const companyName = (recon.company && recon.company.name) || 'Compte';

const sourceKeyToId = new Map((recon.sourceIdByKeyList || []).map((r) => [r.source_key, r.id]));

const sources = (recon.sourcesPayload || []).map((s) => ({
  schemaVersion: 1,
  sourceKey: s.source_key,
  sourceType: s.source_type,
  sourceName: s.source_name,
  sourceUrl: s.source_url || undefined,
  canonicalUrl: s.canonical_url || undefined,
  publishedAt: s.published_at || undefined,
  collectedAt: s.collected_at,
  evidenceExcerpt: s.evidence_excerpt || undefined,
  reliabilityScore: s.reliability_score,
  collectionMethod: s.collection_method,
}));

const fieldProposalsOut = (recon.toInsert || [])
  .filter((p) => !p.attribute_name || ['legal_name', 'siren', 'naf_code', 'description', 'website', 'hq_location', 'sector', 'employee_count', 'revenue'].includes(p.attribute_name))
  .map((p) => ({
    schemaVersion: 1,
    targetType: p.target_type,
    targetId: p.target_id,
    attributeName: p.attribute_name,
    oldValue: (p.initial_snapshot && p.initial_snapshot.current !== undefined) ? p.initial_snapshot.current : null,
    proposedValue: p.proposed_value,
    normalizedValue: p.normalized_value,
    confidenceScore: p.confidence_score,
    sourceKeys: (p.primary_source_id ? [[...sourceKeyToId.entries()].find(([, id]) => id === p.primary_source_id)?.[0]].filter(Boolean) : []),
    justification: p.justification,
  }));

const FACT_ATTRS = new Set([
  'business_model', 'primary_activity', 'technology', 'competitor', 'partner', 'market',
  'strategic_priority', 'transformation_program', 'establishment_count', 'growth_trend',
  'geographic_reach', 'value_proposition', 'differentiators', 'market_position',
  'marketing_position', 'target_customers',
]);

const factProposalsOut = (recon.toInsert || [])
  .filter((p) => FACT_ATTRS.has(p.attribute_name))
  .map((p) => ({
    schemaVersion: 1,
    targetType: p.target_type,
    targetId: p.target_id,
    attributeName: p.attribute_name,
    oldValue: null,
    proposedValue: p.proposed_value,
    normalizedValue: p.normalized_value,
    confidenceScore: p.confidence_score,
    sourceKeys: (p.primary_source_id ? [[...sourceKeyToId.entries()].find(([, id]) => id === p.primary_source_id)?.[0]].filter(Boolean) : []),
    justification: p.justification,
  }));

const accountScanOutput = {
  schemaVersion: 1,
  runId: recon.runId,
  workspaceId: recon.workspaceId,
  companyId: recon.companyId,
  status: 'succeeded',
  resolution: recon.resolution,
  sources,
  fieldProposals: fieldProposalsOut,
  factProposals: factProposalsOut,
  contactCandidates: recon.contactCandidates || [],
  warnings: recon.warnings || [],
};

const reportLines = [`# Scan rapide — ${companyName}`, ''];
if (recon.resolution.status === 'resolved') {
  reportLines.push(`Entité résolue : SIREN ${recon.resolution.siren} (${recon.resolution.matchMethod}).`);
} else if (recon.resolution.status === 'ambiguous') {
  reportLines.push(`Entité ambiguë — ${recon.resolution.candidates.length} candidat(s) à confirmer.`);
} else {
  reportLines.push('Entité juridique non trouvée dans le registre officiel.');
}
reportLines.push(`${fieldProposalsOut.length} proposition(s) de champ, ${factProposalsOut.length} fait(s) proposé(s), ${(recon.contactCandidates || []).length} contact(s) candidat(s), ${sources.length} source(s).`);
if ((recon.warnings || []).length > 0) {
  reportLines.push('', 'Avertissements :', ...recon.warnings.map((w) => `- ${w}`));
}

const callbackBody = {
  runId: recon.runId,
  phase: 1,
  resultType: 'account_scan',
  status: 'succeeded',
  contentJson: accountScanOutput,
  contentText: reportLines.join('\n'),
  title: `Scan rapide — ${companyName}`,
  modelProvider: recon.llmUsage ? 'anthropic' : null,
  modelUsed: (recon.llmUsage && recon.llmUsage.model) || null,
  tokensInput: (recon.llmUsage && recon.llmUsage.inputTokens) || null,
  tokensOutput: (recon.llmUsage && recon.llmUsage.outputTokens) || null,
  contextSnapshot: { company: recon.company, resolution: recon.resolution },
  sourceRefs: [{ entityType: 'company', entityId: recon.companyId, label: 'Fiche compte' }],
  qaFlags: [
    { check: 'entity_resolved', passed: recon.resolution.status === 'resolved', detail: recon.resolution.status },
    { check: 'no_proposal_without_resolved_entity', passed: recon.resolution.status === 'resolved' || (fieldProposalsOut.length === 0 && factProposalsOut.length === 0), detail: 'OK' },
  ],
};

return [{ json: { callbackUrl: recon.callbackUrl, rawBody: JSON.stringify(callbackBody) } }];

const errItem = $input.first().json;
let runId = null;
let callbackUrl = null;

// Plusieurs nœuds peuvent échouer selon le point d'entrée en erreur — on retente dans
// l'ordre du pipeline jusqu'à en trouver un qui a effectivement produit une sortie.
const candidateNodes = [
  'Reconcile & Prepare Writes', 'Merge Scan Result', 'Build Proposals & Sources',
  'Build Unresolved Result', 'Resolve Entity', 'Build Scan Plan', 'Validate & Route',
];
for (const nodeName of candidateNodes) {
  try {
    const j = $(nodeName).first().json;
    if (j && j.runId && j.callbackUrl) {
      runId = j.runId;
      callbackUrl = j.callbackUrl;
      break;
    }
  } catch (e) { /* ce nœud n'a pas produit de sortie exploitable, on essaie le suivant */ }
}

let errorMessage = 'Erreur inconnue dans le workflow intel-010-refresh (account_scan)';
if (errItem && errItem.error) {
  errorMessage = typeof errItem.error === 'string' ? errItem.error : (errItem.error.message || JSON.stringify(errItem.error));
} else if (errItem && errItem.message) {
  errorMessage = errItem.message;
}

const callbackBody = {
  runId,
  phase: 1,
  resultType: 'account_scan',
  status: 'failed',
  contentJson: {},
  errorMessage,
};

return [{ json: { callbackUrl, rawBody: JSON.stringify(callbackBody) } }];
